import './App.css';
import React, { useState, useEffect, useRef } from "react";



const COLORS = {
  primary: "#F0962A",
  cream: "#FBF5EA",
  ink: "#2E2A22",
  sub: "#8A8072",
  line: "#E5E0D5",
  card: "#FFFFFF",
  green: "#DCE9C8",
  greenText: "#5B7A3A",
  placeholderBg: "#EDEAE3",
  placeholderLine: "#CFC8B8",
};

/* ---------------- 공용 부품 ---------------- */

function Logo({ size = 22 }) {
  return (
    <div style={{ display: "flex", alignItems: "center", gap: 8 }}>
      <svg width={size + 8} height={size + 8} viewBox="0 0 40 40">
        <circle cx="20" cy="20" r="18" fill="none" stroke={COLORS.primary} strokeWidth="2.5" />
        <path
          d="M13 15 Q13 12 16 12 L24 12 Q27 12 27 15 L27 20 Q27 26 20 26 Q13 26 13 20 Z"
          fill="none"
          stroke={COLORS.primary}
          strokeWidth="2.2"
        />
        <path d="M20 26 L20 30" stroke={COLORS.primary} strokeWidth="2.2" strokeLinecap="round" />
      </svg>
      <span style={{ fontWeight: 800, fontSize: size, color: COLORS.primary, letterSpacing: "-0.5px" }}>
        한끼<span style={{ color: "#5B7A3A" }}>잇다</span>
      </span>
    </div>
  );
}

/* 지도/사진 등 "나중에 채울 자리"를 표시하는 공용 placeholder */
function Placeholder({ height = 160, label = "이미지 영역", rounded = 12, icon = "🖼️" }) {
  return (
    <div
      style={{
        height,
        borderRadius: rounded,
        border: `1.5px dashed ${COLORS.placeholderLine}`,
        background: COLORS.placeholderBg,
        display: "flex",
        flexDirection: "column",
        alignItems: "center",
        justifyContent: "center",
        gap: 6,
        color: COLORS.sub,
        fontSize: 12.5,
      }}
    >
      <span style={{ fontSize: 22, opacity: 0.6 }}>{icon}</span>
      <span>{label}</span>
    </div>
  );
}

/* 프로필 아바타 자리 (헤더 우측 상단) */
function AvatarPlaceholder({ size = 30 }) {
  return (
    <div
      style={{
        width: size,
        height: size,
        borderRadius: "50%",
        background: COLORS.placeholderBg,
        border: `1px solid ${COLORS.placeholderLine}`,
        flexShrink: 0,
      }}
    />
  );
}

function Header({ onNavigate, active }) {
  const [open, setOpen] = useState(false);
  const ref = useRef(null);

  useEffect(() => {
    function onClick(e) {
      if (ref.current && !ref.current.contains(e.target)) setOpen(false);
    }
    document.addEventListener("mousedown", onClick);
    return () => document.removeEventListener("mousedown", onClick);
  }, []);

  const items = [
    { key: "list", label: "도시락 조회", icon: "🔍" },
    { key: "register", label: "식품 등록", icon: "📋" },
    { key: "mypage", label: "마이페이지", icon: "👤" },
  ];

  return (
    <div
      style={{
        display: "flex",
        alignItems: "center",
        justifyContent: "space-between",
        padding: "14px 18px",
        borderBottom: `1px solid ${COLORS.line}`,
        background: COLORS.card,
        position: "relative",
      }}
    >
      <div onClick={() => onNavigate("home")} style={{ cursor: "pointer" }}>
        <Logo />
      </div>

      <div style={{ display: "flex", alignItems: "center", gap: 12 }}>
        <AvatarPlaceholder />
        <div ref={ref} style={{ position: "relative" }}>
          <button
            onClick={() => setOpen((v) => !v)}
            aria-label="메뉴 열기"
            style={{
              background: "none",
              border: "none",
              cursor: "pointer",
              padding: 6,
              display: "flex",
              flexDirection: "column",
              gap: 4,
            }}
          >
            <span style={{ width: 22, height: 2.5, background: COLORS.ink, borderRadius: 2 }} />
            <span style={{ width: 22, height: 2.5, background: COLORS.ink, borderRadius: 2 }} />
            <span style={{ width: 22, height: 2.5, background: COLORS.ink, borderRadius: 2 }} />
          </button>
          {open && (
            <div
              style={{
                position: "absolute",
                top: 40,
                right: 0,
                background: COLORS.card,
                border: `1px solid ${COLORS.line}`,
                borderRadius: 12,
                boxShadow: "0 10px 30px rgba(0,0,0,0.12)",
                overflow: "hidden",
                width: 168,
                zIndex: 30,
              }}
            >
              {items.map((it) => (
                <div
                  key={it.key}
                  onClick={() => {
                    setOpen(false);
                    onNavigate(it.key);
                  }}
                  style={{
                    display: "flex",
                    alignItems: "center",
                    gap: 10,
                    padding: "13px 16px",
                    fontSize: 14.5,
                    fontWeight: 500,
                    color: active === it.key ? COLORS.primary : COLORS.ink,
                    background: active === it.key ? COLORS.cream : "transparent",
                    cursor: "pointer",
                  }}
                >
                  <span style={{ fontSize: 15 }}>{it.icon}</span>
                  {it.label}
                </div>
              ))}
            </div>
          )}
        </div>
      </div>
    </div>
  );
}

function SearchBar({ value, onChange }) {
  return (
    <div style={{ padding: "12px 18px" }}>
      <div
        style={{
          display: "flex",
          alignItems: "center",
          gap: 8,
          background: "#fff",
          border: `1px solid ${COLORS.line}`,
          borderRadius: 999,
          padding: "10px 16px",
        }}
      >
        <span style={{ color: COLORS.sub }}>⌕</span>
        <input
          value={value}
          onChange={(e) => onChange(e.target.value)}
          placeholder="지역, 제공처명을 검색하세요"
          style={{
            border: "none",
            outline: "none",
            background: "transparent",
            fontSize: 13.5,
            width: "100%",
            color: COLORS.ink,
            fontFamily: "inherit",
          }}
        />
      </div>
    </div>
  );
}

/* ---------------- 데이터 (임시 목데이터) ---------------- */

const PROVIDER = {
  name: "스타벅스 코엑스몰점",
  hours: "13:00 - 13:30",
  address: "서울특별시 마포구 월드컵로 212",
  phone: "02-3153-6114",
  remain: 12,
  items: ["소불고기", "배추김치", "시금치", "잡곡밥", "된장찌개"],
  allergy: "복숭아",
};

/* ---------------- 화면들 ---------------- */

function LoginScreen({ onNavigate }) {
  return (
    <div
      style={{
        height: "100%",
        background: COLORS.cream,
        display: "flex",
        flexDirection: "column",
        alignItems: "center",
        justifyContent: "space-between",
        padding: "56px 28px 40px",
        textAlign: "center",
        boxSizing: "border-box",
      }}
    >
      <Logo size={26} />

      <div style={{ width: "100%" }}>
        <Placeholder height={220} label="음식 이미지 자리" icon="🍱" rounded={20} />
        <p style={{ fontSize: 13.5, color: COLORS.sub, lineHeight: 1.6, marginTop: 18 }}>
          오늘 남은 한 끼,
          <br />
          소중한 마음이 되어 이어집니다.
        </p>
      </div>

      <div style={{ width: "100%", display: "flex", flexDirection: "column", gap: 14 }}>
        <button
          onClick={() => onNavigate("home")}
          style={{
            width: "100%",
            padding: "14px 0",
            background: "#FEE500",
            border: "none",
            borderRadius: 12,
            fontSize: 15,
            fontWeight: 700,
            color: "#391B1B",
            cursor: "pointer",
            display: "flex",
            alignItems: "center",
            justifyContent: "center",
            gap: 8,
          }}
        >
          💬 카카오 로그인
        </button>
        <p style={{ fontSize: 11.5, color: "#B7AE9E", margin: 0 }}>
          소중한 마음이 모여 누군가의 하루를 든든하게 채웁니다.
        </p>
      </div>
    </div>
  );
}

function HomeScreen({ onNavigate, query, setQuery }) {
  return (
    <div style={{ height: "100%", display: "flex", flexDirection: "column" }}>
      <Header onNavigate={onNavigate} active="home" />
      <SearchBar value={query} onChange={setQuery} />
      <div style={{ flex: 1, padding: "0 0 0 0" }}>
        <div style={{ height: "100%", padding: 0 }}>
          <div
            onClick={() => onNavigate("list")}
            style={{ height: "100%", cursor: "pointer" }}
          >
            <Placeholder height="100%" rounded={0} label="지도 영역 (지도 API 연동 예정)" icon="🗺️" />
          </div>
        </div>
      </div>
    </div>
  );
}

function ListScreen({ onNavigate, query, setQuery }) {
  return (
    <div style={{ height: "100%", display: "flex", flexDirection: "column" }}>
      <Header onNavigate={onNavigate} active="list" />
      <SearchBar value={query} onChange={setQuery} />
      <div style={{ position: "relative", flex: 1 }}>
        <Placeholder height="100%" rounded={0} label="지도 영역 (지도 API 연동 예정)" icon="🗺️" />
        <div
          style={{
            position: "absolute",
            left: 12,
            right: 12,
            bottom: 14,
            background: COLORS.card,
            borderRadius: 14,
            boxShadow: "0 10px 30px rgba(0,0,0,0.18)",
            padding: 12,
            display: "flex",
            gap: 12,
            alignItems: "center",
          }}
        >
          <div style={{ width: 58, height: 58, flexShrink: 0 }}>
            <Placeholder height={58} rounded={10} label="" icon="🏪" />
          </div>
          <div style={{ flex: 1, minWidth: 0 }}>
            <div style={{ fontSize: 14, fontWeight: 700, color: COLORS.ink }}>{PROVIDER.name}</div>
            <div style={{ fontSize: 11.5, color: COLORS.sub, marginTop: 2 }}>
              ⏱ {PROVIDER.hours} · 잔여수량 {PROVIDER.remain}개
            </div>
          </div>
          <button
            onClick={() => onNavigate("apply")}
            style={{
              background: COLORS.primary,
              color: "#fff",
              border: "none",
              borderRadius: 10,
              padding: "9px 14px",
              fontSize: 12.5,
              fontWeight: 700,
              cursor: "pointer",
              flexShrink: 0,
            }}
          >
            신청하기
          </button>
        </div>
      </div>
    </div>
  );
}

function ApplyScreen({ onNavigate }) {
  const [time, setTime] = useState("");
  const [agree, setAgree] = useState(false);
  const [toast, setToast] = useState("");

  return (
    <div style={{ height: "100%", display: "flex", flexDirection: "column", position: "relative" }}>
      <Header onNavigate={onNavigate} active="list" />
      <div style={{ padding: 16, overflowY: "auto", flex: 1 }}>
        {/* 제공처 카드 */}
        <div
          style={{
            display: "flex",
            gap: 12,
            padding: 12,
            border: `1px solid ${COLORS.line}`,
            borderRadius: 14,
            marginBottom: 14,
          }}
        >
          <div style={{ width: 72, height: 72, flexShrink: 0 }}>
            <Placeholder height={72} rounded={10} label="" icon="🏪" />
          </div>
          <div>
            <div style={{ fontSize: 14.5, fontWeight: 700, color: COLORS.ink }}>{PROVIDER.name}</div>
            <div style={{ fontSize: 11.5, color: COLORS.sub, marginTop: 4 }}>⏱ {PROVIDER.hours}</div>
            <div style={{ fontSize: 11.5, color: COLORS.sub, marginTop: 2 }}>📍 {PROVIDER.address}</div>
            <div style={{ fontSize: 11.5, color: COLORS.primary, marginTop: 2, fontWeight: 600 }}>
              ☎ {PROVIDER.phone}
            </div>
          </div>
        </div>

        {/* 음식 목록 카드 */}
        <div
          style={{
            display: "flex",
            gap: 12,
            padding: 12,
            border: `1px solid ${COLORS.line}`,
            borderRadius: 14,
            marginBottom: 18,
          }}
        >
          <div style={{ width: 84, height: 84, flexShrink: 0 }}>
            <Placeholder height={84} rounded={10} label="" icon="🍽️" />
          </div>
          <div style={{ flex: 1 }}>
            <ul style={{ margin: 0, paddingLeft: 16, fontSize: 12.5, color: COLORS.ink, lineHeight: 1.7 }}>
              {PROVIDER.items.map((it) => (
                <li key={it}>{it}</li>
              ))}
            </ul>
            <div style={{ marginTop: 8, display: "flex", alignItems: "center", gap: 6 }}>
              <span style={{ fontSize: 11, color: COLORS.sub }}>알러지 주의 식품</span>
              <span
                style={{
                  background: COLORS.green,
                  color: COLORS.greenText,
                  fontSize: 11,
                  fontWeight: 700,
                  padding: "2px 9px",
                  borderRadius: 999,
                }}
              >
                {PROVIDER.allergy}
              </span>
            </div>
          </div>
        </div>

        <div style={{ fontSize: 13, fontWeight: 600, color: COLORS.ink, marginBottom: 8 }}>
          수령 시간을 입력하세요.
        </div>
        <input
          value={time}
          onChange={(e) => setTime(e.target.value)}
          placeholder="예: 오후 1:30"
          style={{
            width: "100%",
            border: `1px solid ${COLORS.line}`,
            borderRadius: 10,
            padding: "12px 14px",
            fontSize: 13.5,
            marginBottom: 18,
            outline: "none",
            fontFamily: "inherit",
            boxSizing: "border-box",
          }}
        />

        <label style={{ display: "flex", gap: 8, alignItems: "flex-start", cursor: "pointer" }}>
          <input
            type="checkbox"
            checked={agree}
            onChange={(e) => setAgree(e.target.checked)}
            style={{ marginTop: 3 }}
          />
          <span style={{ fontSize: 11, color: COLORS.sub, lineHeight: 1.6 }}>
            알레르기 유발 식품 정보를 충분히 확인하였으며, 사전에 고지된 알레르기 정보와 관련하여 발생한 피해에
            대해서는 책임을 묻지 않겠습니다.
          </span>
        </label>
      </div>

      <div style={{ display: "flex", gap: 10, padding: 16, borderTop: `1px solid ${COLORS.line}` }}>
        <button
          onClick={() => onNavigate("list")}
          style={{
            flex: 1,
            padding: "13px 0",
            borderRadius: 10,
            border: `1px solid ${COLORS.line}`,
            background: "#F4F1EA",
            color: COLORS.sub,
            fontWeight: 700,
            fontSize: 13.5,
            cursor: "pointer",
          }}
        >
          취소하기
        </button>
        <button
          disabled={!agree || !time}
          onClick={() => {
            setToast("신청이 완료되었습니다.");
            setTimeout(() => {
              setToast("");
              onNavigate("home");
            }, 1400);
          }}
          style={{
            flex: 1,
            padding: "13px 0",
            borderRadius: 10,
            border: "none",
            background: agree && time ? COLORS.primary : "#F0D4AC",
            color: "#fff",
            fontWeight: 700,
            fontSize: 13.5,
            cursor: agree && time ? "pointer" : "not-allowed",
          }}
        >
          신청하기
        </button>
      </div>

      {toast && (
        <div
          style={{
            position: "absolute",
            bottom: 90,
            left: "50%",
            transform: "translateX(-50%)",
            background: "#2E2A22",
            color: "#fff",
            padding: "10px 18px",
            borderRadius: 999,
            fontSize: 12.5,
            zIndex: 60,
          }}
        >
          {toast}
        </div>
      )}
    </div>
  );
}

function NumberGrid({ count = 8, values, setValues }) {
  return (
    <div style={{ display: "grid", gridTemplateColumns: "repeat(4, 1fr)", gap: 8 }}>
      {Array.from({ length: count }, (_, i) => (
        <input
          key={i}
          value={values[i] || ""}
          onChange={(e) => {
            const next = [...values];
            next[i] = e.target.value;
            setValues(next);
          }}
          placeholder="+"
          style={{
            border: `1px solid ${COLORS.line}`,
            borderRadius: 8,
            padding: "10px 6px",
            fontSize: 12,
            textAlign: "center",
            outline: "none",
            fontFamily: "inherit",
          }}
        />
      ))}
    </div>
  );
}

function RegisterScreen({ onNavigate }) {
  const [menu, setMenu] = useState(Array(8).fill(""));
  const [allergy, setAllergy] = useState(Array(8).fill(""));
  const [qty, setQty] = useState("");
  const [toast, setToast] = useState("");

  return (
    <div style={{ height: "100%", display: "flex", flexDirection: "column", position: "relative" }}>
      <Header onNavigate={onNavigate} active="register" />
      <div style={{ padding: 16, overflowY: "auto", flex: 1 }}>
        <div style={{ display: "flex", alignItems: "center", gap: 10, marginBottom: 16 }}>
          <div style={{ width: 40, height: 40, flexShrink: 0 }}>
            <Placeholder height={40} rounded={10} label="" icon="🏪" />
          </div>
          <div>
            <div style={{ fontSize: 14, fontWeight: 700 }}>{PROVIDER.name}</div>
            <div style={{ fontSize: 11, color: COLORS.sub }}>
              {PROVIDER.hours} · {PROVIDER.address}
            </div>
          </div>
        </div>

        {/* 음식 사진 업로드 자리 (지금은 placeholder만) */}
        <div style={{ marginBottom: 18 }}>
          <Placeholder height={150} label="음식 사진 등록 (추후 업로드 기능 연동)" icon="📷" />
        </div>

        <div style={{ fontSize: 13, fontWeight: 600, marginBottom: 8 }}>■ 메뉴를 입력하세요.</div>
        <div style={{ marginBottom: 18 }}>
          <NumberGrid count={8} values={menu} setValues={setMenu} />
        </div>

        <div style={{ fontSize: 13, fontWeight: 600, marginBottom: 8 }}>■ 수량을 입력하세요.</div>
        <input
          value={qty}
          onChange={(e) => setQty(e.target.value)}
          placeholder="예: 12개"
          style={{
            width: "100%",
            border: `1px solid ${COLORS.line}`,
            borderRadius: 8,
            padding: "11px 12px",
            fontSize: 13,
            marginBottom: 18,
            outline: "none",
            fontFamily: "inherit",
            boxSizing: "border-box",
          }}
        />

        <div style={{ fontSize: 13, fontWeight: 600, marginBottom: 8 }}>■ 알러지 식품을 입력해주세요.</div>
        <NumberGrid count={8} values={allergy} setValues={setAllergy} />
      </div>

      <div style={{ display: "flex", gap: 10, padding: 16, borderTop: `1px solid ${COLORS.line}` }}>
        <button
          onClick={() => onNavigate("home")}
          style={{
            flex: 1,
            padding: "13px 0",
            borderRadius: 10,
            border: `1px solid ${COLORS.line}`,
            background: "#F4F1EA",
            color: COLORS.sub,
            fontWeight: 700,
            fontSize: 13.5,
            cursor: "pointer",
          }}
        >
          취소하기
        </button>
        <button
          onClick={() => {
            setToast("등록이 완료되었습니다.");
            setTimeout(() => {
              setToast("");
              onNavigate("home");
            }, 1400);
          }}
          style={{
            flex: 1,
            padding: "13px 0",
            borderRadius: 10,
            border: "none",
            background: COLORS.primary,
            color: "#fff",
            fontWeight: 700,
            fontSize: 13.5,
            cursor: "pointer",
          }}
        >
          등록하기
        </button>
      </div>

      {toast && (
        <div
          style={{
            position: "absolute",
            bottom: 90,
            left: "50%",
            transform: "translateX(-50%)",
            background: "#2E2A22",
            color: "#fff",
            padding: "10px 18px",
            borderRadius: 999,
            fontSize: 12.5,
            zIndex: 60,
          }}
        >
          {toast}
        </div>
      )}
    </div>
  );
}

function MyPageScreen({ onNavigate }) {
  return (
    <div style={{ height: "100%", display: "flex", flexDirection: "column" }}>
      <Header onNavigate={onNavigate} active="mypage" />
      <div style={{ padding: 24, textAlign: "center", color: COLORS.sub, fontSize: 13 }}>
        마이페이지는 다음 단계에서 설계 예정.
        <br />
        (신청 내역 / 프로필 / 알림 설정 등)
      </div>
    </div>
  );
}

/* ---------------- 최상위 App (라우팅) ---------------- */

export default function App() {
  const [page, setPage] = useState("login");
  const [query, setQuery] = useState("");

  const screens = {
    login: <LoginScreen onNavigate={setPage} />,
    home: <HomeScreen onNavigate={setPage} query={query} setQuery={setQuery} />,
    list: <ListScreen onNavigate={setPage} query={query} setQuery={setQuery} />,
    apply: <ApplyScreen onNavigate={setPage} />,
    register: <RegisterScreen onNavigate={setPage} />,
    mypage: <MyPageScreen onNavigate={setPage} />,
  };

  return (
    <div
      style={{
        minHeight: "100vh",
        background: "#EDEAE2",
        display: "flex",
        alignItems: "center",
        justifyContent: "center",
        fontFamily:
          "'Apple SD Gothic Neo', 'Malgun Gothic', 'Noto Sans KR', sans-serif",
        padding: "24px 0",
      }}
    >
      <div
        style={{
          width: 390,
          height: 780,
          background: COLORS.cream,
          borderRadius: 28,
          overflow: "hidden",
          boxShadow: "0 20px 60px rgba(0,0,0,0.25)",
          position: "relative",
        }}
      >
        {screens[page]}
      </div>
    </div>
  );
}
